html:
{%- set _site = frappe.utils.get_url() -%}
{%- if not sheets and doc -%}
    {%- set is_res = (doc.is_rescheduled == 1 or doc.entrance_test_status == "Rescheduled") -%}
    {%- set f_center = doc.re_center_name if is_res else (doc.center_name or "") -%}
    {%- set f_address = doc.re_center_address if is_res else (doc.center_address or "") -%}
    {%- set f_date = doc.re_allocation_date if is_res else (doc.allocation_date or "") -%}
    {%- set f_prog = doc.program or "" -%}
    {%- set prog_name = frappe.db.get_value("Programme", f_prog, "program_name") or f_prog -%}
    {%- set f_date_fmt = frappe.utils.format_date(f_date, "EEEE, MMMM d, yyyy") if f_date else "" -%}
    {%- set f_start = frappe.utils.format_time(doc.start_time, "hh:mm a") if doc.start_time else "10:00 AM" -%}
    {%- set f_end = frappe.utils.format_time(doc.end_time, "hh:mm a") if doc.end_time else "12:30 PM" -%}
    {%- set f_time_str = f_start ~ " to " ~ f_end -%}
    {%- set f_test = doc.entrance_test_name or "NLSAT 2026" -%}

    {%- set sibling_records = frappe.get_all("Entrance Test Seat Allocation", filters={"center_name": f_center, "program": f_prog}, fields=["name", "applicant", "candidate_name", "admit_card_number", "father_name", "profile"], limit=10, order_by="admit_card_number asc") -%}
    {%- if not sibling_records -%}
        {%- set sibling_records = [doc] -%}
    {%- endif -%}
    {%- set cand_list = [] -%}
    {%- for sr in sibling_records -%}
        {%- set p_src = "" -%}
        {%- set app_photo = frappe.db.get_value("Applicant", sr.applicant, "candidate_photo") if sr.applicant else None -%}
        {%- set target_photo = app_photo or sr.profile -%}
        {%- if target_photo -%}
            {%- set pb64 = get_file_b64(target_photo) -%}
            {%- if not pb64 and sr.profile and sr.profile != target_photo -%}
                {%- set pb64 = get_file_b64(sr.profile) -%}
            {%- endif -%}
            {%- if pb64 -%}
                {%- set p_src = "data:image/jpeg;base64," ~ pb64 -%}
            {%- else -%}
                {%- set p_src = _site ~ target_photo -%}
            {%- endif -%}
        {%- endif -%}
        {%- set _ = cand_list.append({
            "sl_no": loop.index,
            "photo_src": p_src,
            "admit_card_no": sr.admit_card_number,
            "student_name": sr.candidate_name,
            "parent_name": sr.father_name
        }) -%}
    {%- endfor -%}
    {%- set inst_name = frappe.db.get_single_value("Institution Settings", "institution_name") or "National Law School of India University" -%}
    {%- set sheets = [{
        "institution_name": inst_name|upper,
        "center_name": f_center,
        "center_address": f_address,
        "course_name": prog_name,
        "exam_date": f_date_fmt,
        "exam_time": f_time_str,
        "test_title": f_test,
        "pages": [{"page_number": 1, "candidates": cand_list}]
    }] -%}
{%- endif -%}

<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Attendance Sheet</title>
<style>
    @page {
        size: A4 portrait;
        margin-top: 8mm;
        margin-bottom: 8mm;
        margin-left: 10mm;
        margin-right: 10mm;
    }
    * {
        box-sizing: border-box;
        -webkit-box-sizing: border-box;
    }
    html, body {
        margin: 0;
        padding: 0;
        background: #fff;
        font-family: Arial, Helvetica, sans-serif;
        color: #000;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
    .attendance-page {
        width: 100%;
        page-break-after: always;
        padding: 0;
        margin: 0;
    }
    .attendance-page:last-child {
        page-break-after: avoid;
    }
    .univ-header {
        text-align: center;
        margin-top: 4px;
        margin-bottom: 12px;
    }
    .univ-title {
        color: #9E0C0C;
        font-size: 20px;
        font-weight: bold;
        letter-spacing: 0.5px;
        margin: 0 0 3px 0;
        text-transform: uppercase;
    }
    .univ-address {
        color: #333333;
        font-size: 13px;
        margin: 0;
    }
    .info-table {
        width: 100%;
        border-collapse: collapse;
        border: 1.5px solid #000;
        table-layout: fixed;
    }
    .info-table td {
        border: 1.5px solid #000;
        padding: 5px 8px;
        vertical-align: middle;
        font-size: 12px;
    }
    .banner-title {
        text-align: center;
        font-weight: bold;
        font-size: 13px;
        padding: 6px 8px;
        letter-spacing: 0.5px;
    }
    .info-label {
        font-weight: bold;
        text-align: center;
        color: #000;
    }
    .info-value {
        color: #000;
        line-height: 1.3;
    }
    .candidate-table {
        width: 100%;
        border-collapse: collapse;
        border: 1.5px solid #000;
        table-layout: fixed;
        margin-top: 6px;
    }
    .candidate-table th {
        border: 1.5px solid #000;
        padding: 6px 2px;
        text-align: center;
        font-size: 12px;
        font-weight: bold;
        vertical-align: middle;
        line-height: 1.25;
        height: 52px;
    }
    .candidate-table td {
        border: 1.5px solid #000;
        padding: 2px 4px;
        vertical-align: middle;
        font-size: 11.5px;
    }
    .col-sl { width: 4.2%; text-align: center; }
    .col-photo { width: 11.1%; text-align: center; }
    .col-admit { width: 12.5%; text-align: center; font-size: 12px; }
    .col-name { width: 15.3%; text-align: left; text-transform: uppercase; line-height: 1.25; padding: 2px 6px; word-break: break-word; }
    .col-parent { width: 11.1%; text-align: left; text-transform: uppercase; line-height: 1.25; padding: 2px 6px; word-break: break-word; }
    .col-booklet { width: 9.8%; text-align: center; }
    .col-omr { width: 9.7%; text-align: center; }
    .col-sig { width: 26.3%; text-align: center; }

    .photo-box {
        width: 70px;
        height: 88px;
        border: 1.5px solid #000;
        margin: 0 auto;
        overflow: hidden;
        background: #fff;
    }
    .photo-box img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
    .photo-placeholder {
        color: #aaa;
        font-size: 9px;
        text-align: center;
        line-height: 88px;
    }
    .cell-strut {
        height: 99px;
        display: block;
    }
</style>
</head>
<body>

{%- if sheets -%}
{%- for sheet in sheets -%}
{%- for page in sheet.pages -%}
<div class="attendance-page">
    <div class="univ-header">
        <div class="univ-title">{{ (sheet.institution_name or "National Law School of India University") | upper }}</div>
        <div class="univ-address">P.O. Bag 7201, Nagarbhavi, Bangalore - 560 072</div>
    </div>

    <table class="info-table">
        <colgroup>
            <col style="width: 25%;">
            <col style="width: 25%;">
            <col style="width: 25%;">
            <col style="width: 25%;">
        </colgroup>
        <tr>
            <td colspan="4" class="banner-title">
                ATTENDANCE SHEET FOR {{ sheet.test_title or "NLSAT 2026" }}
            </td>
        </tr>
        <tr height="36">
            <td class="info-label">Center Name</td>
            <td class="info-value">{{ sheet.center_name or "" }}</td>
            <td class="info-label">Course Name</td>
            <td class="info-value">{{ sheet.course_name or "" }}</td>
        </tr>
        <tr>
            <td rowspan="2" class="info-label">Center Address</td>
            <td rowspan="2" class="info-value">{{ sheet.center_address or "" }}</td>
            <td class="info-label">Examination Date</td>
            <td class="info-value">{{ sheet.exam_date or "" }}</td>
        </tr>
        <tr>
            <td class="info-label">Examination Time</td>
            <td class="info-value">{{ sheet.exam_time or "" }}</td>
        </tr>
    </table>

    <table class="candidate-table">
        <colgroup>
            <col class="col-sl">
            <col class="col-photo">
            <col class="col-admit">
            <col class="col-name">
            <col class="col-parent">
            <col class="col-booklet">
            <col class="col-omr">
            <col class="col-sig">
        </colgroup>
        <thead>
            <tr height="52">
                <th>Sl<br/>No.</th>
                <th>Photo</th>
                <th>Admit Card<br/>No.</th>
                <th>Name of<br/>Student</th>
                <th>Parent's<br/>Name</th>
                <th>Question<br/>Booklet<br/>No.</th>
                <th>OMR<br/>Sheet No</th>
                <th>Signature</th>
            </tr>
        </thead>
        <tbody>
            {%- for cand in page.candidates -%}
            <tr>
                <td style="text-align: center;">{{ cand.sl_no }}</td>
                <td style="text-align: center;">
                    <div class="photo-box">
                        {%- if cand.photo_src -%}
                            <img src="{{ cand.photo_src }}">
                        {%- else -%}
                            <div class="photo-placeholder">PHOTO</div>
                        {%- endif -%}
                    </div>
                </td>
                <td style="text-align: center;">{{ cand.admit_card_no or "" }}</td>
                <td style="text-align: left;">{{ cand.student_name or "" }}</td>
                <td style="text-align: left;">{{ cand.parent_name or "" }}</td>
                <td><div class="cell-strut"></div></td>
                <td><div class="cell-strut"></div></td>
                <td><div class="cell-strut"></div></td>
            </tr>
            {%- endfor -%}
        </tbody>
    </table>
</div>
{%- endfor -%}
{%- endfor -%}
{%- endif -%}

</body>
</html>
